fn read_config_file(path: Str) -> Str {
  if path.len() == 0 {
    panic("config file path is empty — must provide a valid file path");
  }
  return "server.port=8080\nserver.host=localhost";
}

fn main() -> Int {
  let config = read_config_file("config.xi");
  return config.len();
}
